import React from "react";

export function StatCard({ label = "Total Edge Traffic", value = "1,429,820", delta = "+24.8%" }: { label?: string; value?: string; delta?: string }) {
  return (
    <div className="p-4 rounded-[10px] border border-border bg-card space-y-2 shadow-sm">
      <div className="flex items-center justify-between text-xs text-muted-foreground">
        <span>{label}</span>
        <span className="font-mono text-emerald-600 font-semibold bg-emerald-500/10 px-1.5 py-0.5 rounded-[4px]">{delta}</span>
      </div>
      <div className="text-2xl font-bold font-mono text-foreground">{value}</div>
    </div>
  );
}
